// src/core/categories/categories.schemas.ts
import { z } from 'zod';
import type { CategoryContext } from '@unificard/contracts';

// ===============================
// Contextos canônicos permitidos
// ===============================
export const CATEGORY_CONTEXT_VALUES: CategoryContext[] = [
  'professional',
  'interest',
  'education',
  'hobby',
  'learning',
  'health',     // Saúde (autodeclaração, NUNCA diagnóstico)
  'company',
  'lifestyle',
];

// ===============================
// Helpers canônicos
// ===============================
const slugSchema = z
  .string()
  .min(1)
  .max(200)
  .regex(/^[a-z0-9-]+$/, 'Slug deve conter apenas letras minúsculas, números e hífens');

const uuidSchema = z.string().uuid('UUID inválido');

// ===============================
// Criação manual (humano / admin)
// ===============================
export const createCategorySchema = z.object({
  name: z.string().min(1).max(200),
  slug: slugSchema.optional(),
  description: z.string().max(5000).nullable().optional(),

  // Estrutura
  parentId: uuidSchema.nullable().optional(),

}).superRefine((data, ctx) => {
  // Root explícito ou child explícito, nunca ambíguo
  if (data.parentId === undefined) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: 'parentId deve ser explicitamente null (root) ou UUID (child)',
    });
  }
});

// ===============================
// Criação em lote (seed controlado)
// ===============================
export const createManyCategoriesSchema = z.object({
  categories: z.array(z.object({
    name: z.string().min(1).max(200),
    slug: slugSchema.optional(),
    description: z.string().max(5000).nullable().optional(),

    // Apenas UMA forma de vínculo
    parentSlug: z.string().nullable().optional(),
  })).min(1),
}).superRefine((data, ctx) => {
  const slugs = new Set<string>();

  for (const cat of data.categories) {
    if (cat.slug) {
      if (slugs.has(cat.slug)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: `Slug duplicado no batch: ${cat.slug}`,
        });
      }
      slugs.add(cat.slug);
    }
  }
});

// ===============================
// Associação empresa ↔ categoria
// ===============================
export const assignCategoryToCompanySchema = z.object({
  companyId: uuidSchema,
  categoryId: uuidSchema,
});

// ===============================
// Skill do usuário
// ===============================
export const assignSkillToUserSchema = z.object({
  categoryId: uuidSchema,
  skillLevel: z.number().int().min(0).max(100).optional(),
});

// ===============================
// Classificação de texto (NÃO cria)
// ===============================
export const classifyTextSchema = z.object({
  text: z.string().min(1).max(10000),
  maxCategories: z.number().int().min(1).max(10).optional(),
});

// ===============================
// IA — proposição, NÃO criação livre
// ===============================
export const aiCreateCategorySchema = z.object({
  text: z.string().min(1).max(500),

  context: z
    .enum(CATEGORY_CONTEXT_VALUES as [CategoryContext, ...CategoryContext[]])
    .default('professional'),

  parentId: uuidSchema.nullable().optional(),

  countryCode: z
    .string()
    .length(2, 'Código do país deve ter 2 caracteres (ISO 3166-1 alpha-2)')
    .nullable()
    .optional(),

  inputType: z.enum(['text', 'voice', 'transcription']).default('text'),

  audioUrl: z.string().url().optional(),
  audioHash: z.string().length(64).optional(),

}).superRefine((data, ctx) => {
  // IA nunca cria root implicitamente
  if (data.parentId === undefined) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: 'IA não pode criar categoria sem parentId explícito',
    });
  }
});
